1	package meter
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7	)
8	
9	// 本文件回归“结清最后一笔到期欠款”与“上报一条新用量”同时发生时的用量接收
10	// 结果，防止日后把停用判定、扣款与用量累计拆成多个不同步的步骤而破坏以下
11	// 不变量：
12	//
13	// 规则是按处理新事件那一刻的欠费情况决定是否接收：付款不会自动替用户补录
14	// 刚被拒绝的事件。因此同一账户上一笔恰好结清到期账单的付款与一条当前账期
15	// 的新事件并发到达时，终态只能与两种串行顺序之一一致：
16	//
17	//   - 用量先于付款裁决：上报返回 ErrSuspended，当前账期累计仍为 0；随后付款
18	//     成功结清也不能把这次拒绝改写成已接收（不能出现上报失败却累计增加）。
19	//   - 付款先于用量裁决：上报成功，Accepted 为 true、返回当前账期，累计变为
20	//     事件数量（不能出现上报成功却没有累计）。
21	//
22	// 无论用量走哪条路径：
23	//
24	//   - 最后一笔付款都必须是首次登记成功，返回账单余额 0 与已付清；旧账单的
25	//     应付金额与截止时刻保持出账时的值，付款只改变已付金额与余额。
26	//   - 结清后账户不再欠费停用，但订阅条件（开通时的套餐快照）不因付款改变。
27	//   - 原样再次提交该事件：首次被拒的路径本次按首次接收（Accepted=true），
28	//     首次已成功的路径按重报幂等返回（Accepted=false）；两条路径此后累计都
29	//     恰好等于事件数量，被拒收不消耗事件标识，成功接收不重复计量。
30	//
31	// 时间线（全部 UTC）：
32	//
33	//	2026-01-01 00:00 开通套餐 plan1000（月费 1000，无超额、无税），订阅持续
34	//	           有效：不取消、不换套餐。
35	//	2026-02-10 00:00 为已结束的 2026-01 出账：应付 1000，截止时刻固定为
36	//	           2026-02-08 00:00（已到期）。先用付款标识 pay-partial 登记
37	//	           400 分，账单仍欠 600 分，账户欠费停用；2026-02 尚未出账、
38	//	           累计用量为 0，账户没有其他欠款。
39	//	同一时刻并发到达两项合法请求：
40	//	   - 用新付款标识 pay-rest 登记剩余 600 分；
41	//	   - 用此前未接收的标识 evt-feb-3 上报发生在当前时刻、数量 3 的事件，
42	//	     归属于尚未出账的 2026-02。
43	
44	const (
45		finalPayAcct  = "acct-final-payment"
46		finalPayID    = "pay-rest"
47		partialPayID  = "pay-partial"
48		finalEventID  = "evt-feb-3"
49		finalBillDue  = 1000
50		finalPaidPart = 400
51		finalPayRest  = 600
52		finalEventQty = 3
53	)
54	
55	var (
56		finalPayNow   = utc(2026, 2, 10, 0, 0)
57		finalDueAt    = utc(2026, 2, 8, 0, 0)
58		finalSubStart = utc(2026, 1, 1, 0, 0)
59	)
60	
61	// suspendedFinalPaymentFixture 搭好题述起点：订阅持续有效，一月旧账单应付
62	// 1000、已登记 400、仍欠 600 且已过截止时刻，账户欠费停用；二月未出账、
63	// 累计用量为 0。结束时时钟停在 2026-02-10 00:00。
64	func suspendedFinalPaymentFixture(t *testing.T) (*Service, *fakeClock) {
65		t.Helper()
66		s, clk := newTestService(finalSubStart)
67		mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
68		mustAccount(t, s, finalPayAcct)
69		if err := s.Subscribe(finalPayAcct, "plan1000", finalSubStart); err != nil {
70			t.Fatalf("subscribe: %v", err)
71		}
72	
73		clk.t = finalPayNow
74		bill, err := s.CreateBill(finalPayAcct, jan(2026))
75		if err != nil {
76			t.Fatalf("create jan bill: %v", err)
77		}
78		if bill.TotalDue != finalBillDue || bill.Paid != 0 || bill.Balance != finalBillDue || bill.Settled {
79			t.Fatalf("jan bill initial state: %+v", bill)
80		}
81		if !bill.DueAt.Equal(finalDueAt) {
82			t.Fatalf("jan bill due at = %v, want %v", bill.DueAt, finalDueAt)
83		}
84	
85		partial, err := s.RecordPayment(finalPayAcct, partialPayID, jan(2026), finalPaidPart)
86		if err != nil || !partial.Registered || partial.BillBalance != finalPayRest || partial.Settled {
87			t.Fatalf("partial payment 400: r=%+v err=%v", partial, err)
88		}
89	
90		// 起点：欠费停用但订阅仍有效，套餐条件保持开通快照；二月无账无用量。
91		st, err := s.Status(finalPayAcct)
92		if err != nil {
93			t.Fatalf("status at fixture: %v", err)
94		}
95		if !st.Subscribed || !st.Suspended {
96			t.Fatalf("fixture flags: subscribed=%v suspended=%v, want true/true", st.Subscribed, st.Suspended)
97		}
98		if st.CurrentTerms != termsOf(Plan{ID: "plan1000", MonthlyFee: 1000}) {
99			t.Fatalf("fixture terms changed: %+v", st.CurrentTerms)
100		}
101		if u, _ := s.MonthlyUsage(finalPayAcct, feb(2026)); u.Total != 0 {
102			t.Fatalf("fixture feb usage = %d, want 0", u.Total)
103		}
104		if _, err := s.GetBill(finalPayAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
105			t.Fatalf("fixture feb bill should not exist: %v", err)
106		}
107		return s, clk
108	}
109	
110	// finalPayEvent 返回那条与结清付款竞争的二月事件（数量 3，发生在当前时刻）。
111	func finalPayEvent() Event {
112		return Event{AccountID: finalPayAcct, EventID: finalEventID, At: finalPayNow, Quantity: finalEventQty}
113	}
114	
115	// recordRestPayment 登记最后一笔 600 分付款；first 为 true 时断言首次登记，
116	// 否则断言原样重报（Registered=false，返回首次登记完成时的历史结果 0/已付清）。
117	func recordRestPayment(t *testing.T, s *Service, first bool) PaymentResult {
118		t.Helper()
119		r, err := s.RecordPayment(finalPayAcct, finalPayID, jan(2026), finalPayRest)
120		if err != nil {
121			t.Fatalf("record final payment 600: %v", err)
122		}
123		want := Payment{AccountID: finalPayAcct, PaymentID: finalPayID, Period: jan(2026), Amount: finalPayRest}
124		if r.Payment != want {
125			t.Fatalf("final payment content = %+v, want %+v", r.Payment, want)
126		}
127		if r.Registered != first {
128			t.Fatalf("final payment registered = %v, want %v", r.Registered, first)
129		}
130		if r.BillBalance != 0 || !r.Settled {
131			t.Fatalf("final payment result: balance=%d settled=%v, want 0/true", r.BillBalance, r.Settled)
132		}
133		return r
134	}
135	
136	// wantJanBillSettled 校验一月旧账单：已付 1000、余额 0、已付清；应付金额、
137	// 用量明细与截止时刻保持出账时的固定值，不被任何付款或上报改动。
138	func wantJanBillSettled(t *testing.T, s *Service) {
139		t.Helper()
140		b, err := s.GetBill(finalPayAcct, jan(2026))
141		if err != nil {
142			t.Fatalf("get jan bill: %v", err)
143		}
144		if b.TotalDue != finalBillDue || b.Paid != finalBillDue || b.Balance != 0 || !b.Settled {
145			t.Fatalf("jan bill state: due=%d paid=%d balance=%d settled=%v, want 1000/1000/0/true",
146				b.TotalDue, b.Paid, b.Balance, b.Settled)
147		}
148		if b.MonthlyFee != 1000 || b.OverageFee != 0 || b.Tax != 0 || b.TotalUsage != 0 ||
149			b.IncludedUnits != 0 || b.OverageUnits != 0 {
150			t.Fatalf("jan bill fixed detail changed: %+v", b)
151		}
152		if !b.DueAt.Equal(finalDueAt) {
153			t.Fatalf("jan bill due at = %v, want %v", b.DueAt, finalDueAt)
154		}
155	}
156	
157	// wantRestoredSubscription 校验结清后：不再欠费停用、订阅仍生效且套餐条件
158	// 仍是开通时保存的 plan1000 快照——付款只解除停用，不改变订阅。
159	func wantRestoredSubscription(t *testing.T, s *Service) AccountStatus {
160		t.Helper()
161		st, err := s.Status(finalPayAcct)
162		if err != nil {
163			t.Fatalf("status after payment: %v", err)
164		}
165		if !st.Subscribed || st.Suspended {
166			t.Fatalf("flags after payment: subscribed=%v suspended=%v, want true/false",
167				st.Subscribed, st.Suspended)
168		}
169		if st.CurrentTerms != termsOf(Plan{ID: "plan1000", MonthlyFee: 1000}) {
170			t.Fatalf("terms changed by payment: %+v", st.CurrentTerms)
171		}
172		if st.PendingChange != nil || st.ScheduledEnd != nil {
173			t.Fatalf("payment fabricated plan change / cancellation: %+v", st)
174		}
175		return st
176	}
177	
178	// wantFebTotal 同时通过 MonthlyUsage 与 Status 校验二月累计用量。二月从未
179	// 接收过事件且未出账时，Status 的用量列表里本就不包含该账期（与零值等价），
180	// 因此 want 为 0 时允许其缺省。
181	func wantFebTotal(t *testing.T, s *Service, want int64) {
182		t.Helper()
183		u, err := s.MonthlyUsage(finalPayAcct, feb(2026))
184		if err != nil {
185			t.Fatalf("monthly usage: %v", err)
186		}
187		if u.Period != feb(2026) || u.Total != want {
188			t.Fatalf("feb monthly usage = %+v, want total %d", u, want)
189		}
190		st, err := s.Status(finalPayAcct)
191		if err != nil {
192			t.Fatalf("status: %v", err)
193		}
194		var found bool
195		for _, su := range st.MonthlyUsage {
196			if su.Period == feb(2026) {
197				found = true
198				if su.Total != want {
199					t.Fatalf("feb status usage = %d, want %d", su.Total, want)
200				}
201			}
202		}
203		if !found && want != 0 {
204			t.Fatalf("feb usage missing from status, want total %d: %+v", want, st.MonthlyUsage)
205		}
206	}
207	
208	// TestUsageBeforeFinalPaymentRejectedThenAccepted 确定性覆盖第一种顺序：
209	// 新用量在付款结清之前被处理，必须返回 ErrSuspended 且不累计；付款随后
210	// 成功也不能改写这次拒绝。拒收不消耗事件标识，结清后原样提交按首次接收，
211	// 再提交才是幂等重报。
212	func TestUsageBeforeFinalPaymentRejectedThenAccepted(t *testing.T) {
213		s, clk := suspendedFinalPaymentFixture(t)
214		ev := finalPayEvent()
215	
216		// 停用期间上报：ErrSuspended，当前账期累计仍为 0。
217		if _, err := s.RecordEvent(ev); !errors.Is(err, ErrSuspended) {
218			t.Fatalf("event while suspended: r err=%v, want ErrSuspended", err)
219		}
220		wantFebTotal(t, s, 0)
221	
222		// 付款随后成功结清：首次登记，返回余额 0、已付清。
223		recordRestPayment(t, s, true)
224		// 旧账单只更新已付与余额；应付与截止时刻保持出账时的值。
225		wantJanBillSettled(t, s)
226		// 不再欠费停用，订阅条件不因付款改变。
227		wantRestoredSubscription(t, s)
228		// 付款成功不替用户补录刚被拒绝的事件：二月累计仍为 0。
229		wantFebTotal(t, s, 0)
230	
231		// 原样提交刚才被拒的事件：拒收没有占用标识，本次作为首次接收。
232		r, err := s.RecordEvent(ev)
233		if err != nil || !r.Accepted || r.Period != feb(2026) {
234			t.Fatalf("resubmit rejected event: r=%+v err=%v, want accepted into 2026-02", r, err)
235		}
236		wantFebTotal(t, s, finalEventQty)
237	
238		// 再次原样提交：此时才是已接收事件的重报，Accepted=false、不重复计量。
239		if r, err := s.RecordEvent(ev); err != nil || r.Accepted || r.Period != feb(2026) {
240			t.Fatalf("identical replay after acceptance: r=%+v err=%v", r, err)
241		}
242		wantFebTotal(t, s, finalEventQty)
243	
244		// 最后一笔付款原样重报：不再次登记，返回首次登记完成时的历史结果
245		// （余额 0、已付清），账单当前状态不变。
246		recordRestPayment(t, s, false)
247		wantJanBillSettled(t, s)
248		wantFebTotal(t, s, finalEventQty)
249	
250		// 时钟未被任何操作推动；二月始终未出账。
251		if !clk.t.Equal(finalPayNow) {
252			t.Fatalf("clock moved unexpectedly: %v", clk.t)
253		}
254		if _, err := s.GetBill(finalPayAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
255			t.Fatalf("feb bill should still not exist: %v", err)
256		}
257	}
258	
259	// TestPaymentBeforeUsageEventAcceptedThenReplayed 确定性覆盖第二种顺序：
260	// 付款先完成、账户恢复，上报成功并累计 3；再次原样提交为重报（Accepted
261	// =false），不重复计量。
262	func TestPaymentBeforeUsageEventAcceptedThenReplayed(t *testing.T) {
263		s, clk := suspendedFinalPaymentFixture(t)
264		ev := finalPayEvent()
265	
266		// 付款先完成：首次登记，余额 0、已付清，账户立即解除停用。
267		recordRestPayment(t, s, true)
268		wantJanBillSettled(t, s)
269		wantRestoredSubscription(t, s)
270	
271		// 上报新用量：首次接收成功，归入尚未出账的 2026-02，累计变为 3。
272		r, err := s.RecordEvent(ev)
273		if err != nil || !r.Accepted || r.Period != feb(2026) {
274			t.Fatalf("event after payment: r=%+v err=%v, want accepted into 2026-02", r, err)
275		}
276		wantFebTotal(t, s, finalEventQty)
277	
278		// 原样重报：Accepted=false、账期仍为 2026-02，不再次累计。
279		if r, err := s.RecordEvent(ev); err != nil || r.Accepted || r.Period != feb(2026) {
280			t.Fatalf("identical replay: r=%+v err=%v", r, err)
281		}
282		wantFebTotal(t, s, finalEventQty)
283	
284		// 付款重报仍返回首次登记时的历史结果（0/已付清），不再次增加已付金额。
285		recordRestPayment(t, s, false)
286		wantJanBillSettled(t, s)
287		wantFebTotal(t, s, finalEventQty)
288	
289		if !clk.t.Equal(finalPayNow) {
290			t.Fatalf("clock moved unexpectedly: %v", clk.t)
291		}
292		if _, err := s.GetBill(finalPayAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
293			t.Fatalf("feb bill should still not exist: %v", err)
294		}
295	}
296	
297	// paymentEventOutcome 收集并发竞争中一方的原始返回，供按顺序分类断言。
298	type paymentEventOutcome struct {
299		payR   PaymentResult
300		payErr error
301		evR    EventResult
302		evErr  error
303	}
304	
305	// TestFinalPaymentConcurrentWithNewUsage 真并发版本：用启动屏障让“登记剩余
306	// 600”与“上报数量 3 的二月事件”在同一时刻争用同一账户。实现把两者的
307	// 全部裁决都放在同一把互斥锁的一个临界区内，因此终态必须且只能与两种
308	// 串行顺序之一一致：
309	//
310	//   - 事件先裁决：事件 ErrSuspended、累计为 0；
311	//   - 付款先裁决：事件 Accepted=true、累计为 3。
312	//
313	// 两种顺序下付款都必须首次登记成功（余额 0、已付清）。并发结束后再原样
314	// 提交事件：被拒路径首次接收（Accepted=true），已接收路径幂等重报
315	// （Accepted=false），两条路径最终累计都恰为 3，不允许失败却累计或成功
316	// 却不累计。
317	func TestFinalPaymentConcurrentWithNewUsage(t *testing.T) {
318		const rounds = 200
319		for iter := 0; iter < rounds; iter++ {
320			s, _ := suspendedFinalPaymentFixture(t)
321			ev := finalPayEvent()
322	
323			var oc paymentEventOutcome
324			var wg sync.WaitGroup
325			start := make(chan struct{})
326			wg.Add(2)
327			go func() {
328				defer wg.Done()
329				<-start
330				oc.payR, oc.payErr = s.RecordPayment(finalPayAcct, finalPayID, jan(2026), finalPayRest)
331			}()
332			go func() {
333				defer wg.Done()
334				<-start
335				oc.evR, oc.evErr = s.RecordEvent(ev)
336			}()
337			close(start)
338			wg.Wait()
339	
340			// 付款与用量先后无关：最后一笔付款都首次登记成功，恰好结清账单。
341			if oc.payErr != nil || !oc.payR.Registered ||
342				oc.payR.Payment != (Payment{AccountID: finalPayAcct, PaymentID: finalPayID, Period: jan(2026), Amount: finalPayRest}) ||
343				oc.payR.BillBalance != 0 || !oc.payR.Settled {
344				t.Fatalf("iter %d concurrent payment: r=%+v err=%v", iter, oc.payR, oc.payErr)
345			}
346	
347			// 事件只能是“被停用拒绝”或“首次接收成功”二者之一；并发首报绝不能
348			// 命中重报（Accepted=false 且无错误），也不能返回任何其他错误。
349			eventRejected := false
350			switch {
351			case errors.Is(oc.evErr, ErrSuspended):
352				eventRejected = true
353			case oc.evErr == nil && oc.evR.Accepted && oc.evR.Period == feb(2026):
354				// 付款先裁决：首次接收。
355			default:
356				t.Fatalf("iter %d concurrent event: r=%+v err=%v", iter, oc.evR, oc.evErr)
357			}
358	
359			// 自洽性：返回结果必须与累计用量一致——失败却累计增加、成功却没有
360			// 累计都不允许。
361			u, err := s.MonthlyUsage(finalPayAcct, feb(2026))
362			if err != nil {
363				t.Fatalf("iter %d monthly usage: %v", iter, err)
364			}
365			if eventRejected {
366				if u.Total != 0 {
367					t.Fatalf("iter %d rejected event accumulated %d", iter, u.Total)
368				}
369			} else if u.Total != finalEventQty {
370				t.Fatalf("iter %d accepted event missing accumulation, total=%d", iter, u.Total)
371			}
372	
373			// 无论哪种顺序，账单已结清、固定字段不变，账户恢复且订阅条件不变。
374			wantJanBillSettled(t, s)
375			wantRestoredSubscription(t, s)
376	
377			// 并发结束后原样再提交同一事件：被拒路径本次首次接收，成功路径本次
378			// 幂等重报；两条路径此刻起累计都恰为 3。
379			r2, err := s.RecordEvent(ev)
380			if err != nil {
381				t.Fatalf("iter %d second submit: %v", iter, err)
382			}
383			if r2.Accepted != eventRejected {
384				t.Fatalf("iter %d second submit accepted=%v, eventRejected=%v", iter, r2.Accepted, eventRejected)
385			}
386			if r2.Period != feb(2026) {
387				t.Fatalf("iter %d second submit period=%s", iter, r2.Period)
388			}
389			wantFebTotal(t, s, finalEventQty)
390	
391			// 第三次提交无论哪条路径都是重报：Accepted=false，累计不再变化。
392			if r3, err := s.RecordEvent(ev); err != nil || r3.Accepted || r3.Period != feb(2026) {
393				t.Fatalf("iter %d third submit: r=%+v err=%v", iter, r3, err)
394			}
395			wantFebTotal(t, s, finalEventQty)
396	
397			// 付款重报不再次登记；二月始终未出账。
398			recordRestPayment(t, s, false)
399			if _, err := s.GetBill(finalPayAcct, feb(2026)); !errors.Is(err, ErrBillNotFound) {
400				t.Fatalf("iter %d feb bill should not exist: %v", iter, err)
401			}
402		}
403	}
